( function () {
'use strict';
var KEY = 'rsh_privacy';
var YEAR = 365 * 24 * 60 * 60 * 1000;
var box = document.querySelector( '[data-rsh-privacy]' );
if ( ! box ) {
return;
}
var version = box.getAttribute( 'data-rsh-privacy' );
var ok = box.querySelector( '[data-rsh-privacy-ok]' );
var opener = null;
function stored() {
try {
var value = JSON.parse( window.localStorage.getItem( KEY ) || 'null' );
return value && value.v === version && Date.now() - value.t < YEAR;
} catch ( e ) {
return false;
}
}
function remember() {
try {
window.localStorage.setItem( KEY, JSON.stringify( { v: version, t: Date.now() } ) );
} catch ( e ) {
}
}
function open( focus ) {
box.hidden = false;
if ( focus ) {
opener = document.activeElement;
box.focus();
}
}
function close() {
remember();
box.hidden = true;
if ( opener && opener.focus ) {
opener.focus();
}
opener = null;
}
ok.addEventListener( 'click', close );
box.addEventListener( 'keydown', function ( event ) {
if ( 'Escape' === event.key ) {
close();
}
} );
Array.prototype.slice.call( document.querySelectorAll( '[data-rsh-privacy-open]' ) ).forEach( function ( button ) {
button.hidden = false;
button.addEventListener( 'click', function () {
open( true );
} );
} );
if ( ! stored() ) {
open( false );
}
}() );
